fields.InputDefinition:
{
  "goal": "Open the AI application using the application switcher dropdown next to the logo (NOT the Ctrl+K search box), then open the Agents section. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) agents-tree-view — in the toolbar there is a Grid / List / Tree view toggle; click the Tree (Category Tree View, folder-tree icon) option and confirm the agents re-render as a hierarchical category tree (agents grouped under expandable category branches) instead of the card grid (a valid empty tree state also counts); (2) agents-category-filter — click the Filter button/icon in the toolbar to open the filter popover, find the Category filter (a tree-style folder-tree dropdown), open it and pick a category value, then confirm the agent list responds (narrows to matches OR shows a clear no-match/empty state). Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "agents-tree-view",
      "instruction": "toggle the Agents view to the Category Tree",
      "visualCriteria": [
        "The Grid/List/Tree view toggle is visible and clicking Tree changes the layout from cards to a hierarchical tree with expandable category branches and agents as leaf nodes, OR a clearly labelled empty tree state"
      ]
    },
    {
      "name": "agents-category-filter",
      "instruction": "open the filter popover and apply a Category tree-dropdown value",
      "visualCriteria": [
        "The filter popover opens and displays filter fields including a Category tree-style dropdown widget; selecting a category value causes the agent list to update (narrow to matches) or show a clear no-results state"
      ]
    }
  ]
}
